import { createLocalSlateTestClient, expectSlateError } from '@slates/test';
import type { SlateAxiosErrorOptions } from 'slates';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { provider } from './index';

let state = vi.hoisted(() => ({
  nextError: undefined as unknown,
  errorMapping: undefined as unknown
}));

vi.mock('slates', async importOriginal => {
  let actual = await importOriginal<typeof import('slates')>();

  let request = async () => {
    if (state.nextError === undefined) {
      return { data: {} };
    }

    let error = state.nextError;

    // Mirror the shared slates response interceptor, which converts axios
    // failures into SlateErrors using the instance's errorMapping.
    if (
      typeof error === 'object' &&
      error !== null &&
      (error as { isAxiosError?: unknown }).isAxiosError === true
    ) {
      error = actual.SlateError.fromAxios(
        error,
        state.errorMapping as SlateAxiosErrorOptions | undefined
      );
    }

    throw error;
  };

  return {
    ...actual,
    createAxios: (config?: Record<string, unknown>) => {
      state.errorMapping = config?.errorMapping;

      return {
        interceptors: {
          response: {
            use: () => {}
          }
        },
        get: request
      };
    }
  };
});

let createClient = () => createLocalSlateTestClient({ slate: provider });

let axiosError = (status: number, statusText: string, data: unknown) => {
  let error = new Error(`Request failed with status code ${status}`);
  Object.assign(error, {
    isAxiosError: true,
    config: { method: 'get', url: '/', baseURL: 'https://example.test:9243' },
    response: { status, statusText, data, headers: {} }
  });
  return error;
};

beforeEach(() => {
  state.nextError = undefined;
  state.errorMapping = undefined;
});

describe('elasticsearch auth contract', () => {
  it('returns the normalized auth output when credentials validate', async () => {
    let result = await createClient().getAuthOutput({
      authenticationMethodId: 'api_key',
      input: {
        elasticsearchUrl: 'https://example.test:9243/',
        token: 'encoded-key'
      }
    });

    expect(result.output).toMatchObject({
      baseUrl: 'https://example.test:9243',
      authHeader: 'ApiKey encoded-key'
    });
  });

  it('surfaces the Elasticsearch security reason when basic authentication fails', async () => {
    state.nextError = axiosError(401, 'Unauthorized', {
      error: {
        root_cause: [
          {
            type: 'security_exception',
            reason: 'unable to authenticate user [elastic] for REST request [/]'
          }
        ],
        type: 'security_exception',
        reason: 'unable to authenticate user [elastic] for REST request [/]'
      },
      status: 401
    });

    let error = await expectSlateError(
      () =>
        createClient().getAuthOutput({
          authenticationMethodId: 'basic_auth',
          input: {
            elasticsearchUrl: 'https://example.test:9243',
            username: 'elastic',
            password: 'wrong-password'
          }
        }),
      {
        code: 'auth.invalid',
        status: 401
      }
    );

    let data = (error as { data: { message: string; upstream?: { code?: string } } }).data;
    expect(data.message).toContain('unable to authenticate user [elastic]');
    expect(data.upstream?.code).toBe('security_exception');
  });

  it('surfaces the Elasticsearch security reason when an API key lacks permissions', async () => {
    state.nextError = axiosError(403, 'Forbidden', {
      error: {
        root_cause: [
          {
            type: 'security_exception',
            reason: 'action [cluster:monitor/main] is unauthorized for API key'
          }
        ],
        type: 'security_exception',
        reason: 'action [cluster:monitor/main] is unauthorized for API key'
      },
      status: 403
    });

    let error = await expectSlateError(
      () =>
        createClient().getAuthOutput({
          authenticationMethodId: 'api_key',
          input: {
            elasticsearchUrl: 'https://example.test:9243',
            token: 'restricted-key'
          }
        }),
      {
        code: 'permission.denied',
        status: 403
      }
    );

    let data = (error as { data: { message: string } }).data;
    expect(data.message).toContain(
      'action [cluster:monitor/main] is unauthorized for API key'
    );
  });
});

import { createLocalSlateTestClient } from '@slates/test';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { googleSearchConsoleScopes } from './scopes';

let oauthPost = vi.fn();
let profileGet = vi.fn();

let loadProviderClient = async () => {
  vi.resetModules();
  oauthPost.mockReset();
  profileGet.mockReset();

  vi.doMock('slates', async () => {
    let actual = await vi.importActual<typeof import('slates')>('slates');

    return {
      ...actual,
      createAxios: vi.fn((config?: { baseURL?: string }) => {
        if (config?.baseURL === 'https://oauth2.googleapis.com') {
          return {
            post: oauthPost
          };
        }

        if (config?.baseURL === 'https://www.googleapis.com') {
          return {
            get: profileGet
          };
        }

        return actual.createAxios(config);
      })
    };
  });

  let { provider } = await import('./index');
  return createLocalSlateTestClient({ slate: provider });
};

afterEach(() => {
  vi.doUnmock('slates');
  vi.resetModules();
});

describe('google-search-console auth contract', () => {
  it('builds the expected OAuth authorization URL', async () => {
    let client = await loadProviderClient();
    let result = await client.getAuthorizationUrl({
      authenticationMethodId: 'oauth',
      redirectUri: 'https://example.com/callback',
      state: 'state-123',
      input: {},
      clientId: 'client-id',
      clientSecret: 'client-secret',
      scopes: [
        googleSearchConsoleScopes.webmastersReadonly,
        googleSearchConsoleScopes.userInfoEmail
      ]
    });

    let url = new URL(result.authorizationUrl);
    expect(`${url.origin}${url.pathname}`).toBe(
      'https://accounts.google.com/o/oauth2/v2/auth'
    );
    expect(url.searchParams.get('scope')).toBe(
      `${googleSearchConsoleScopes.webmastersReadonly} ${googleSearchConsoleScopes.userInfoEmail}`
    );
  });

  it('maps callback and refresh token responses into the stored auth shape', async () => {
    let client = await loadProviderClient();

    oauthPost.mockResolvedValueOnce({
      data: {
        access_token: 'access-token',
        refresh_token: 'refresh-token',
        expires_in: 3600,
        scope: `${googleSearchConsoleScopes.webmasters} ${googleSearchConsoleScopes.userInfoProfile}`
      }
    });

    let callbackResult = await client.handleAuthorizationCallback({
      authenticationMethodId: 'oauth',
      code: 'auth-code',
      state: 'state-123',
      redirectUri: 'https://example.com/callback',
      input: {},
      clientId: 'client-id',
      clientSecret: 'client-secret',
      scopes: [googleSearchConsoleScopes.webmasters]
    });

    expect(callbackResult.output).toMatchObject({
      token: 'access-token',
      refreshToken: 'refresh-token'
    });
    expect(callbackResult.scopes).toEqual([
      googleSearchConsoleScopes.webmasters,
      googleSearchConsoleScopes.userInfoProfile
    ]);
    expect(Date.parse(String(callbackResult.output.expiresAt))).toBeGreaterThan(Date.now());

    oauthPost.mockResolvedValueOnce({
      data: {
        access_token: 'refreshed-token',
        expires_in: 1800
      }
    });

    let refreshResult = await client.refreshToken({
      authenticationMethodId: 'oauth',
      output: {
        token: 'stale-token',
        refreshToken: 'refresh-token'
      },
      input: {},
      clientId: 'client-id',
      clientSecret: 'client-secret',
      scopes: [googleSearchConsoleScopes.webmasters]
    });

    expect(refreshResult.output).toMatchObject({
      token: 'refreshed-token',
      refreshToken: 'refresh-token'
    });
    expect(Date.parse(String(refreshResult.output.expiresAt))).toBeGreaterThan(Date.now());
  });

  it('returns the existing output when refreshing without a refresh token', async () => {
    let client = await loadProviderClient();

    let refreshResult = await client.refreshToken({
      authenticationMethodId: 'oauth',
      output: {
        token: 'only-access'
      },
      input: {},
      clientId: 'client-id',
      clientSecret: 'client-secret',
      scopes: [googleSearchConsoleScopes.webmastersReadonly]
    });

    expect(refreshResult.output).toEqual({ token: 'only-access' });
    expect(oauthPost).not.toHaveBeenCalled();
  });

  it('maps the Google profile payload into the Slate profile shape', async () => {
    let client = await loadProviderClient();

    profileGet.mockResolvedValueOnce({
      data: {
        id: 'user-123',
        email: 'gsc-test@example.com',
        name: 'GSC Test User',
        picture: 'https://example.com/avatar.png'
      }
    });

    let result = await client.getAuthProfile({
      authenticationMethodId: 'oauth',
      output: {
        token: 'profile-token'
      },
      input: {},
      scopes: [googleSearchConsoleScopes.userInfoProfile]
    });

    expect(result.profile).toEqual({
      id: 'user-123',
      email: 'gsc-test@example.com',
      name: 'GSC Test User',
      imageUrl: 'https://example.com/avatar.png'
    });
  });
});

import { SlateTool } from '@slates/provider';
import { z } from 'zod';
import { Client } from '../lib/client';
import { spec } from '../spec';

export let testActionStep = SlateTool.create(spec, {
  name: 'Test Action Step',
  key: 'test_action_step',
  description: `Test a configured Zapier action step with the provided authentication and inputs. Zapier executes the action against the target app and returns the third-party result payload.`,
  instructions: [
    'Use this after resolving required fields and before creating a Zap.',
    'This may execute the selected third-party action, so prefer harmless test inputs or clean up any created resources.'
  ],
  tags: {
    destructive: false
  }
})
  .input(
    z.object({
      actionId: z.string().describe('Action ID from the /v2/actions endpoint'),
      authenticationId: z
        .string()
        .nullable()
        .describe('Authentication ID to use for testing the action'),
      inputs: z.record(z.string(), z.any()).describe('Input values to test with the action'),
      limit: z
        .number()
        .optional()
        .describe('Maximum number of test results to return when supported'),
      offset: z.number().optional().describe('Pagination offset when supported')
    })
  )
  .output(
    z.object({
      results: z.array(z.any()).describe('Result data returned by the tested action'),
      totalCount: z.number().describe('Total number of results returned by Zapier')
    })
  )
  .handleInvocation(async ctx => {
    let client = new Client({ token: ctx.auth.token });

    let response = await client.testStep(ctx.input.actionId, {
      authentication: ctx.input.authenticationId,
      inputs: ctx.input.inputs,
      limit: ctx.input.limit,
      offset: ctx.input.offset
    });

    let results = Array.isArray(response?.data) ? response.data : [];
    let totalCount =
      typeof response?.meta?.count === 'number' ? response.meta.count : results.length;

    return {
      output: {
        results,
        totalCount
      },
      message: `Tested action \`${ctx.input.actionId}\` and received **${results.length}** result(s).`
    };
  })
  .build();

